window.DEX_DATA["sources:backport-f44ed6ba50aab4cf"]={"json":{"skins":[{"filename":"punkguy.png"}],"names":[{"name":"斯文"},{"name":"尤金"},{"name":"丹尼斯"},{"name":"唐尼"},{"name":"斯派克"}],"chat":[{"lines":[{"text":"上周末我去听演唱会，还参加了冲撞舞！"},{"text":"真不该让格斗属性宝可梦参加那种活动。"}]},{"lines":[{"text":"喜欢我的夹克吗？真皮的。"},{"text":"从一般风格变成朋克风格，简直是升级啊！"}]},{"lines":[{"text":"我可不是坏人，我特别喜欢自己的臭泥。"},{"text":"有时让她骑在我头上，虽然有点臭，但特别酷。"}]},{"lines":[{"text":"我想找几个不在乎规矩的朋友……"},{"text":"来一场宝可梦大混战。"}]}]}};
